uint32_t MmQueryAddressProtect(uint32_t address); // kernel/vmem.cpp

extern "C" PPC_FUNC(__imp__sub_8295A518);
PPC_EXTERN_FUNC(sub_82CE4FF8); // XPhysicalFree(address)
PPC_EXTERN_FUNC(sub_82CE4C88); // VirtualFree(address, size, type)

// sub_8295A518: Free of the engine's pooled allocator (this r3, pointer r4). Blocks over 16 KB that
// fit 4 KB pages better are taken from the OS outside the pools (sub_8295A438, physical ones with
// PAGE_READWRITE and no MEM_LARGE_PAGES), and Free tells them apart by address: on the console those
// physical blocks live in the 4 KB-page view, 0xE0000000+. Here every game physical block is at
// 0xA0000000-0xBFFFFFFF (kernel/vmem.cpp), so Free looked them up in the pool tables, found an empty
// entry and wrote through null (crash on the phone a little after boot). They go back to the OS here,
// the way Free's 0xE0000000 branch does.
PPC_FUNC(sub_8295A518)
{
    const uint32_t pointer = ctx.r4.u32;
    if (pointer >= 0xA0000000 && pointer < 0xC0000000)
    {
        constexpr uint32_t X_MEM_LARGE_PAGES = 0x20000000;
        constexpr uint32_t X_MEM_16MB_PAGES = 0x80000000;
        const uint32_t protect = MmQueryAddressProtect(pointer);
        if (protect != 0 && !(protect & (X_MEM_LARGE_PAGES | X_MEM_16MB_PAGES)))
        {
            const uint32_t self = ctx.r3.u32;
            static std::atomic<int> s_logged{ 0 };
            if (s_logged.fetch_add(1) < 4)
                LOGF_WARNING("pooled Free of a 4 KB-page physical block 0x{:08X}: back to the OS", pointer);
            ctx.r3.u64 = pointer;
            if (PPC_LOAD_U32(self + 12188) != 0) // set by the PhysicalAlloc/PhysicalFree wrappers
            {
                sub_82CE4FF8(ctx, base);
            }
            else
            {
                ctx.r4.u64 = 0;
                ctx.r5.u64 = 0x8000; // MEM_RELEASE
                sub_82CE4C88(ctx, base);
            }
            return;
        }
    }
    __imp__sub_8295A518(ctx, base);
}

static std::string GuestWideString(uint8_t* base, uint32_t address, uint32_t maxLength = 200)
{
    std::string text;
    for (uint32_t i = 0; address != 0 && i < maxLength; i++)
    {
        const uint16_t c = PPC_LOAD_U16(address + 2 * i);
        if (c == 0)
            break;
        text += c < 0x80 ? char(c) : '?';
    }
    return text;
}

extern "C" PPC_FUNC(__imp__sub_8253A428);

// sub_8253A428: UGameEngine::LoadMap(this r3, FURL r4, pending r5, FString& error r6). Every map is
// opened with ?listen, and with no sockets here the listen fails and leaves "Error initializing
// network layer." in the error, while the map loaded (result 1). UGearEngine::LoadMap (sub_82A0B7A0)
// then skips what comes after a clean load: the ?chapter= option, which is the one that loads the
// chapter's map. "New campaign" goes through GearGame_P, an empty map, so the campaign stayed there:
// a black world where the player falls and dies. Single player needs no listening, so a map that
// loaded is not an error.
PPC_FUNC(sub_8253A428)
{
    const uint32_t error = ctx.r6.u32;
    __imp__sub_8253A428(ctx, base);
    if (ctx.r3.u32 != 0 && error != 0 && PPC_LOAD_U32(error + 4) != 0)
    {
        static std::atomic<int> s_logged{ 0 };
        if (s_logged.fetch_add(1) < 4)
            LOGF_WARNING("map loaded, its error dropped: {}", GuestWideString(base, PPC_LOAD_U32(error)));
        PPC_STORE_U32(error + 4, 0);
    }
}

extern "C" PPC_FUNC(__imp__sub_824105B0);

namespace
{
    // A launcher switch (runtime/os/launcher_ui.cpp, Gráficos y GPU): 1 on, 0 off; on when unset
    // (the PC, or an APK started without the launcher).
    bool SwitchedOff(const char* name)
    {
        const char* value = std::getenv(name);
        return value != nullptr && std::strcmp(value, "0") == 0;
    }

    struct SettingValue
    {
        uint32_t offset; // in FSystemSettingsData: a 32-bit UBOOL or INT
        const char* key; // its SystemSettings ini key
        uint32_t value;
    };

    // Sombras off: the real-time shadows (characters, objects, the sun on them). The world's baked
    // shadows are in its light maps and stay.
    constexpr SettingValue kNoShadows[] = {
        {884, "DynamicShadows", 0},
        {888, "LightEnvironmentShadows", 0},
        {932, "bEnableForegroundShadowsOnWorld", 0},
        {936, "bEnableForegroundSelfShadowing", 0},
        {940, "bAllowWholeSceneDominantShadows", 0},
    };

    // Efectos off: the image effects (full-screen passes every frame), and the particles one LOD down.
    constexpr SettingValue kNoEffects[] = {
        {52, "MotionBlur", 0},
        {60, "DepthOfField", 0},
        {64, "AmbientOcclusion", 0},
        {68, "Bloom", 0},
        {72, "bAllowLightShafts", 0},
        {76, "Distortion", 0},
        {92, "LensFlares", 0},
        {124, "AllowRadialBlur", 0},
    };
    constexpr uint32_t kParticleLODBias = 112; // an INT added to each particle system's LOD level
}

// sub_824105B0: FSystemSettingsData::LoadFromIni(this r3, section r4, ini r5, ...), the engine's
// SystemSettings (its {key, member} table resolved from the code; a BasedOn section is read by
// calling itself, so the outermost call has the last word). The launcher's Gráficos switches
// (XPORT_SHADOWS, XPORT_EFFECTS) go over what the ini says, in every copy the engine loads.
PPC_FUNC(sub_824105B0)
{
    const uint32_t settings = ctx.r3.u32;
    __imp__sub_824105B0(ctx, base);
    const bool noShadows = SwitchedOff("XPORT_SHADOWS"), noEffects = SwitchedOff("XPORT_EFFECTS");
    if (settings == 0 || (!noShadows && !noEffects))
        return;
    std::string changed;
    const auto set = [&](const SettingValue& setting)
    {
        const uint32_t old = PPC_LOAD_U32(settings + setting.offset);
        if (old == setting.value)
            return;
        PPC_STORE_U32(settings + setting.offset, setting.value);
        changed += fmt::format(" {} {}->{}", setting.key, old, setting.value);
    };
    if (noShadows)
    {
        for (const SettingValue& setting : kNoShadows)
            set(setting);
    }
    if (noEffects)
    {
        for (const SettingValue& setting : kNoEffects)
            set(setting);
        if (int32_t(PPC_LOAD_U32(settings + kParticleLODBias)) < 1)
            set({kParticleLODBias, "ParticleLODBias", 1});
    }
    static std::atomic<int> s_logged{ 0 };
    if (s_logged.fetch_add(1) < 8)
        LOGF_WARNING("system settings 0x{:08X}: launcher shadows {}, effects {}:{}", settings, noShadows ? "off" : "on",
                     noEffects ? "off" : "on", changed.empty() ? " already so" : changed);
}

// Builds before the LoadMap fix above left "New campaign" in GearGame_P, and the game saved its
// checkpoint there (GearsCheckpoint<N>.sav starting with u32 3, u32 11, "GearGame_P"). Continuing
// from it makes the level start recurse without end (sub_8264FD00, stack overflow a second after the
// map loads, on the phone and on the PC). The console never saves in that map: such a checkpoint is
// emptied, which is how the game writes a free slot, and a copy is kept beside the saves.
static void DropLoaderMapCheckpoints()
{
    std::error_code error;
    const std::filesystem::path folder = os::paths::GetSavePath() / "GearsCheckpoint";
    for (const auto& entry : std::filesystem::directory_iterator(folder, error))
    {
        const std::filesystem::path path = entry.path();
        if (!entry.is_regular_file(error) || path.extension() != ".sav")
            continue;
        uint8_t header[19] = {};
        {
            std::ifstream file(path, std::ios::binary);
            file.read(reinterpret_cast<char*>(header), sizeof(header));
            if (file.gcount() != std::streamsize(sizeof(header)))
                continue;
        }
        const uint32_t version = uint32_t(header[0]) << 24 | header[1] << 16 | header[2] << 8 | header[3];
        const uint32_t length = uint32_t(header[4]) << 24 | header[5] << 16 | header[6] << 8 | header[7];
        static const char kLoaderMap[] = "geargame_p";
        bool loaderMap = version == 3 && length == sizeof(kLoaderMap) && header[18] == 0;
        for (size_t i = 0; loaderMap && i + 1 < sizeof(kLoaderMap); i++)
            loaderMap = std::tolower(header[8 + i]) == kLoaderMap[i];
        if (!loaderMap)
            continue;
        const std::filesystem::path copy =
            os::paths::GetSavePath() / (path.filename().string() + ".geargame_p.bak");
        std::filesystem::copy_file(path, copy, std::filesystem::copy_options::overwrite_existing, error);
        std::filesystem::resize_file(path, 0, error);
        LOGF_WARNING("checkpoint {} was saved in the loader map GearGame_P: emptied ({}), copy in {}",
                     path.filename().string(), error ? error.message() : "ok", copy.string());
    }
}

